@Component({
  selector: 'app-nueva-tarea',
  template: `
    <input (input)="alEscribir($event)" (keyup.enter)="guardar()" />
    <button type="button" (click)="guardar()">Agregar</button>
  `,
})
export class NuevaTarea {
  titulo = '';

  alEscribir(evento: Event) {
    this.titulo = (evento.target as HTMLInputElement).value;
  }

  guardar() {
    console.log('Guardar', this.titulo);
  }
}
